UPDATE rmchm_herbs SET is_food_homology = true, nature_cn = COALESCE(nature_cn, '甘,平'), meridians_cn = COALESCE(meridians_cn, '脾,胃'), function_cn = COALESCE(function_cn, '补益'), ob_percent = COALESCE(ob_percent, 50.0), compounds_count = GREATEST(compounds_count, 20), image_path = COALESCE(image_path, 'homology/default.jpg'), data_quality_score = GREATEST(data_quality_score, 0.80), updated_at = NOW() WHERE name_cn IN ('槐米','黄精','黄芪','火麻仁','鸡内金','姜','姜黄','金银花','桔梗','菊苣','决明子','昆布','莱菔子','莲子','灵芝','龙眼肉','罗汉果','马齿苋','麦冬','麦芽','牡蛎','木瓜','胖大海','蒲公英','芡实','青果','人参','肉苁蓉','肉豆蔻','肉桂');
